-- Questions and answers the owner manages in Admin -> FAQ: site-wide ones (home page + /faq) and ones that belong to one class
-- (shown on that class's page). A new table only, so the release that is still running while this one rolls out keeps working.
CREATE TABLE faqs (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  scope       TEXT NOT NULL DEFAULT 'site' CHECK (scope IN ('site','course')),
  course_id   INTEGER REFERENCES courses(id),                -- the class a 'course' question belongs to; NULL for site-wide ones
  topic       TEXT NOT NULL DEFAULT 'general' CHECK (topic IN ('general','payment','learning','certificate','refund')),
  question_bn TEXT NOT NULL DEFAULT '',
  question_en TEXT NOT NULL DEFAULT '',
  answer_bn   TEXT NOT NULL DEFAULT '',                      -- simple Markdown: **bold**, - lists, [links](/path)
  answer_en   TEXT NOT NULL DEFAULT '',
  featured    INTEGER NOT NULL DEFAULT 0,                    -- site-wide only: also shown on the home page
  active      INTEGER NOT NULL DEFAULT 1,
  sort        INTEGER NOT NULL DEFAULT 100,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),
  deleted_at  TEXT,
  CHECK ((scope = 'site' AND course_id IS NULL) OR (scope = 'course' AND course_id IS NOT NULL))
);
CREATE INDEX idx_faqs_live ON faqs(scope, course_id, active, sort) WHERE deleted_at IS NULL;

-- Starter questions. Every answer describes what the site really does today and nothing else (no invented prices, times or
-- promises); the owner can edit or remove any of them in Admin -> FAQ.

INSERT INTO faqs (scope, topic, question_bn, question_en, answer_bn, answer_en, featured, sort) VALUES ('site', 'general', 'কীভাবে ক্লাসে ভর্তি হব?', 'How do I join a class?', 'একটি বিনামূল্যের অ্যাকাউন্ট খুলুন, পছন্দের ক্লাসটি খুলে **এখনই ভর্তি হন** চাপুন। চেকআউটে টাকা দিন (ফ্রি ক্লাস হলে এক ক্লিকেই ভর্তি)। এরপর ক্লাসটি **আমার ক্লাস**-এ চলে আসবে এবং সাথে সাথেই প্রথম লেসন শুরু করতে পারবেন।', 'Create a free account, open the class you like and press **Enroll Now**. Pay at checkout (a free class opens with one click). The class then appears in **My Learning** and you can start the first lesson right away.', 1, 10);
INSERT INTO faqs (scope, topic, question_bn, question_en, answer_bn, answer_en, featured, sort) VALUES ('site', 'payment', 'কোন কোন পদ্ধতিতে টাকা দেওয়া যায়?', 'Which payment methods can I use?', 'চেকআউট পেজে এই মুহূর্তে চালু থাকা সব পেমেন্ট পদ্ধতি দেখতে পাবেন — যেমন বিকাশ, নগদ বা রকেটের মতো মোবাইল ওয়ালেট, কার্ড, অথবা ম্যানুয়ালি সেন্ড মানি। পছন্দের পদ্ধতিটি বেছে নিয়ে পর্দার ধাপগুলো অনুসরণ করুন — কী করতে হবে পাতাটিই বলে দেবে।', 'On the checkout page you will see every payment method that is open right now — for example mobile wallets such as bKash, Nagad or Rocket, cards, or sending money manually. Choose the one you prefer and follow the steps on the screen; the page tells you exactly what to do.', 1, 20);
INSERT INTO faqs (scope, topic, question_bn, question_en, answer_bn, answer_en, featured, sort) VALUES ('site', 'payment', 'সেন্ড মানিতে টাকা পাঠিয়েছি, ক্লাস কখন খুলবে?', 'I paid by Send Money. When will my class open?', 'টাকা পাঠানোর পর পেমেন্ট পেজে ট্রানজ্যাকশন আইডি (TrxID) দিন এবং/অথবা পেমেন্টের স্ক্রিনশট আপলোড করুন। আমাদের টিম সেটি পেমেন্ট স্টেটমেন্টের সাথে মিলিয়ে ক্লাসটি খুলে দেবে; অপেক্ষার সময় পাতাটিতে অবস্থা দেখা যাবে। পাতার টাইমার শেষ হয়ে গেলেও তথ্য পাঠিয়ে দিন — আমরা প্রতিটি পেমেন্ট যাচাই করি।', 'After you send the money, enter the transaction ID (TrxID) and/or upload a screenshot on the payment page. Our team checks it against our payment statement and opens the class for you; the page shows the status while you wait. If the timer on the page has already run out, send the details anyway — we check every payment.', 1, 30);
INSERT INTO faqs (scope, topic, question_bn, question_en, answer_bn, answer_en, featured, sort) VALUES ('site', 'learning', 'লেসন কোথায় এবং কীভাবে দেখব?', 'Where and how do I watch the lessons?', 'লগইন করে **আমার ক্লাস** খুলুন। ফোন, ট্যাবলেট বা কম্পিউটার — যেকোনোটিতে লেসন দেখা যায় এবং প্রতিটি লেসন শেষ করার সাথে সাথে আপনার অগ্রগতি সেভ হয়। ভিডিও সুরক্ষিত: শুধু ক্লাসে ভর্তি শিক্ষার্থীরাই সেগুলো চালাতে পারেন।', 'Log in and open **My Learning**. Lessons play on your phone, tablet or computer, and your progress is saved lesson by lesson. Videos are protected: only students enrolled in the class can play them.', 1, 40);
INSERT INTO faqs (scope, topic, question_bn, question_en, answer_bn, answer_en, featured, sort) VALUES ('site', 'learning', 'কেনার আগে কি ক্লাসটি একটু দেখে নেওয়া যায়?', 'Can I try a class before I buy it?', 'কিছু ক্লাসের লেসনে **ফ্রি প্রিভিউ** লেখা থাকে — অ্যাকাউন্ট বা পেমেন্ট ছাড়াই যে কেউ সেগুলো দেখতে পারেন। ক্লাসের পাতায় লেসনের তালিকায় লেবেলটি খুঁজুন।', 'Some classes have lessons marked **Free preview** — anyone can watch those without an account or payment. Open the class page and look for the label in the lesson list.', 0, 50);
INSERT INTO faqs (scope, topic, question_bn, question_en, answer_bn, answer_en, featured, sort) VALUES ('site', 'learning', 'কোথাও আটকে গেলে কি প্রশ্ন করা যায়?', 'What if I get stuck? Can I ask a question?', 'হ্যাঁ। প্রতিটি লেসনে **প্রশ্ন ও উত্তর** অংশে **প্রশ্ন করুন** বাটন আছে। আমাদের টিম সেখানেই উত্তর দেয়, তাই আপনার প্রশ্নের নিচেই উত্তর পাবেন।', 'Yes. Every lesson has a **Questions & answers** area with an **Ask a question** button. Our team answers there, so you will find the reply under your question.', 0, 60);
INSERT INTO faqs (scope, topic, question_bn, question_en, answer_bn, answer_en, featured, sort) VALUES ('site', 'certificate', 'সার্টিফিকেট পাব কি?', 'Do I get a certificate?', 'ক্লাসে সার্টিফিকেট থাকলে সব লেসন (১০০%) শেষ করার সাথে সাথে সেটি নিজে থেকেই তৈরি হয়ে যায়। সার্টিফিকেটে একটি ভেরিফিকেশন কোড থাকে এবং যে কেউ [সার্টিফিকেট যাচাই](/verify) পাতায় সেটি মিলিয়ে দেখতে পারেন।', 'If the class includes one, your certificate is issued automatically when you finish every lesson (100%). It has a verification code, and anyone can check it on the [Verify certificate](/en/verify) page.', 1, 70);
INSERT INTO faqs (scope, topic, question_bn, question_en, answer_bn, answer_en, featured, sort) VALUES ('site', 'general', 'পাসওয়ার্ড ভুলে গেছি, কী করব?', 'I forgot my password. What do I do?', 'লগইন পেজে **পাসওয়ার্ড ভুলে গেছেন?** চাপুন, ইমেইল দিন — আমরা পাসওয়ার্ড রিসেট করার লিংক পাঠাব। ইমেইল না এলে আমাদের মেসেজ করুন, আমরা সাহায্য করব।', 'On the login page press **Forgot your password?**, enter your email and we will send you a reset link. If the email does not arrive, message us and we will help.', 0, 80);
INSERT INTO faqs (scope, topic, question_bn, question_en, answer_bn, answer_en, featured, sort) VALUES ('site', 'refund', 'রিফান্ড নীতি কী?', 'What is your refund policy?', 'আমাদের রিফান্ডের নিয়ম [রিফান্ড নীতি](/policies/refund) পাতায় লেখা আছে। আপনার নিজের অর্ডার নিয়ে কোনো প্রশ্ন থাকলে অর্ডার নম্বরসহ আমাদের মেসেজ করুন, আমরা দেখব।', 'Our refund rules are written on the [Refund policy](/en/policies/refund) page. If you have a question about your own order, message us with your order number and we will look into it.', 0, 90);
INSERT INTO faqs (scope, topic, question_bn, question_en, answer_bn, answer_en, featured, sort) VALUES ('site', 'general', 'আপনাদের সাথে কীভাবে যোগাযোগ করব?', 'How can I contact you?', 'হোয়াটসঅ্যাপে মেসেজ করুন, অথবা ফোন, ইমেইল ও সোশ্যাল লিংকের জন্য [যোগাযোগ](/contact) পাতা খুলুন। পেমেন্ট নিয়ে প্রশ্ন হলে অনুগ্রহ করে অর্ডার নম্বর জানাবেন।', 'Message us on WhatsApp, or open the [Contact](/en/contact) page for our phone, email and social links. If your question is about a payment, please include your order number.', 0, 100);
